package android.net;import java.util.*;public final class Uri {final java.net.URI v;private Uri(String s){v=java.net.URI.create(s);}public static Uri parse(String s){return new Uri(s);}public String getAuthority(){return v.getAuthority();}public String getPath(){return v.getPath();}public List<String> getPathSegments(){return Arrays.stream(v.getPath().split("/")).filter(s->!s.isEmpty()).toList();}public String toString(){return v.toString();}}
